// ============================================================================
// QSPI_XIP_apb: APB4 register wrapper around QSPI_XIP_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/QSPI_XIP.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/QSPI_XIP.md
// ============================================================================
module QSPI_XIP_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic sclk,
  output logic csn,
  inout tri [3:0] io,
  input logic [3:0] s_awid,
  input logic [31:0] s_awaddr,
  input logic [7:0] s_awlen,
  input logic [2:0] s_awsize,
  input logic [1:0] s_awburst,
  input logic s_awvalid,
  output logic s_awready,
  input logic [31:0] s_wdata,
  input logic [3:0] s_wstrb,
  input logic s_wlast,
  input logic s_wvalid,
  output logic s_wready,
  output logic [3:0] s_bid,
  output logic [1:0] s_bresp,
  output logic s_bvalid,
  input logic s_bready,
  input logic [3:0] s_arid,
  input logic [31:0] s_araddr,
  input logic [7:0] s_arlen,
  input logic [2:0] s_arsize,
  input logic [1:0] s_arburst,
  input logic s_arvalid,
  output logic s_arready,
  output logic [3:0] s_rid,
  output logic [31:0] s_rdata,
  output logic [1:0] s_rresp,
  output logic s_rlast,
  output logic s_rvalid,
  input logic s_rready
);
  localparam logic [31:0] ID_VALUE = 32'h5C530100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [13:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd14) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [7:0]    c_div;
  logic          c_quad;
  logic [7:0]    c_pc_cmd;
  logic          c_pc_has_addr;
  logic [23:0]   c_pc_addr;
  logic [2:0]    c_pc_nwr;
  logic [2:0]    c_pc_nrd;
  logic [31:0]   c_pc_wdata;
  logic          c_pc_start;
  logic [31:0]   c_pc_rdata;
  logic          c_pc_busy;
  logic          c_pc_done;
  logic [15:0]   c_xip_cmds;
  logic [15:0]   c_xip_beats;
  QSPI_XIP_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .sclk(sclk),
    .csn(csn),
    .io(io),
    .div(c_div),
    .quad(c_quad),
    .pc_cmd(c_pc_cmd),
    .pc_has_addr(c_pc_has_addr),
    .pc_addr(c_pc_addr),
    .pc_nwr(c_pc_nwr),
    .pc_nrd(c_pc_nrd),
    .pc_wdata(c_pc_wdata),
    .pc_start(c_pc_start),
    .pc_rdata(c_pc_rdata),
    .pc_busy(c_pc_busy),
    .pc_done(c_pc_done),
    .xip_cmds(c_xip_cmds),
    .xip_beats(c_xip_beats),
    .s_awid(s_awid),
    .s_awaddr(s_awaddr),
    .s_awlen(s_awlen),
    .s_awsize(s_awsize),
    .s_awburst(s_awburst),
    .s_awvalid(s_awvalid),
    .s_awready(s_awready),
    .s_wdata(s_wdata),
    .s_wstrb(s_wstrb),
    .s_wlast(s_wlast),
    .s_wvalid(s_wvalid),
    .s_wready(s_wready),
    .s_bid(s_bid),
    .s_bresp(s_bresp),
    .s_bvalid(s_bvalid),
    .s_bready(s_bready),
    .s_arid(s_arid),
    .s_araddr(s_araddr),
    .s_arlen(s_arlen),
    .s_arsize(s_arsize),
    .s_arburst(s_arburst),
    .s_arvalid(s_arvalid),
    .s_arready(s_arready),
    .s_rid(s_rid),
    .s_rdata(s_rdata),
    .s_rresp(s_rresp),
    .s_rlast(s_rlast),
    .s_rvalid(s_rvalid),
    .s_rready(s_rready)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [8:0] r_CFG;   // 12'h014 CFG
  logic [14:0] r_PC_CTRL;   // 12'h018 PC_CTRL
  logic [23:0] r_PC_ADDR;   // 12'h01C PC_ADDR
  logic [31:0] r_PC_WDATA;   // 12'h020 PC_WDATA
  logic [0:0] p_CMD;   // 12'h024 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 9'h101;
      r_PC_CTRL <= 15'h0;
      r_PC_ADDR <= 24'h0;
      r_PC_WDATA <= 32'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[6]) r_PC_CTRL <= (r_PC_CTRL & ~wmask[14:0]) | (PWDATA[14:0] & wmask[14:0]);
      if (wr && hit[7]) r_PC_ADDR <= (r_PC_ADDR & ~wmask[23:0]) | (PWDATA[23:0] & wmask[23:0]);
      if (wr && hit[8]) r_PC_WDATA <= (r_PC_WDATA & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[9]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_div = r_CFG[7:0];
  assign c_quad = r_CFG[8:8];
  assign c_pc_cmd = r_PC_CTRL[7:0];
  assign c_pc_has_addr = r_PC_CTRL[8:8];
  assign c_pc_nwr = r_PC_CTRL[11:9];
  assign c_pc_nrd = r_PC_CTRL[14:12];
  assign c_pc_addr = r_PC_ADDR[23:0];
  assign c_pc_wdata = r_PC_WDATA[31:0];
  assign c_pc_start = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_pc_done;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG);
      10'd6: apb_rdata = 32'(r_PC_CTRL);
      10'd7: apb_rdata = 32'(r_PC_ADDR);
      10'd8: apb_rdata = 32'(r_PC_WDATA);
      10'd10: apb_rdata = 32'({c_pc_rdata});
      10'd11: apb_rdata = 32'({c_pc_busy});
      10'd12: apb_rdata = 32'({c_xip_cmds});
      10'd13: apb_rdata = 32'({c_xip_beats});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
